-- H2 test schema for opportunity/notice/AI/eligibility/checklist/precheck (V2 + V10 + V11 projections).
-- Simplified to the columns the module actually touches; production DDL stays in sql/V10,V11.
CREATE TABLE notices(id BIGINT PRIMARY KEY,campus_id BIGINT,title VARCHAR(256),content VARCHAR(100000),raw_url VARCHAR(1024),publisher VARCHAR(128),published_at TIMESTAMP,source_type VARCHAR(16) DEFAULT 'manual',source_name VARCHAR(128),external_id VARCHAR(128),official_reference VARCHAR(512),is_stale BOOLEAN DEFAULT FALSE,status VARCHAR(32) DEFAULT 'pending',version INT DEFAULT 0,attachment_id BIGINT,created_by BIGINT,updated_by BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE ai_parse_tasks(id BIGINT PRIMARY KEY,notice_id BIGINT,async_job_id BIGINT,model VARCHAR(64),status VARCHAR(32) DEFAULT 'pending',result_json VARCHAR(8192),confidence DECIMAL(5,4),error VARCHAR(1024),input_digest CHAR(64),claim_token CHAR(32),picked_at TIMESTAMP,next_retry_at TIMESTAMP,retry_count INT DEFAULT 0,prompt_template_version VARCHAR(64),duration_ms INT,reviewed_by BIGINT,review_decision VARCHAR(16),review_reason VARCHAR(512),opportunity_draft_id BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE ai_parse_fields(id BIGINT PRIMARY KEY,parse_task_id BIGINT,field_key VARCHAR(64),field_value VARCHAR(8192),evidence_location VARCHAR(512),confidence DECIMAL(5,4),human_confirmed BOOLEAN DEFAULT FALSE,human_value VARCHAR(8192),created_at TIMESTAMP);
CREATE TABLE opportunities(id BIGINT PRIMARY KEY,campus_id BIGINT,notice_id BIGINT,title VARCHAR(256),category VARCHAR(32),organizer VARCHAR(128),summary VARCHAR(100000),deadline TIMESTAMP,status VARCHAR(32) DEFAULT 'published',source_type VARCHAR(16) DEFAULT 'manual',rules_version INT DEFAULT 0,version INT DEFAULT 0,created_by BIGINT,updated_by BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE opportunity_eligibility_rules(id BIGINT PRIMARY KEY,opportunity_id BIGINT,field_key VARCHAR(64),operator VARCHAR(16),value_json VARCHAR(4000),severity VARCHAR(16) DEFAULT 'hard',sort_order INT DEFAULT 0,created_at TIMESTAMP);
CREATE TABLE opportunity_eligibility_checks(id BIGINT PRIMARY KEY,opportunity_id BIGINT,user_id BIGINT,conclusion VARCHAR(16),reason_json VARCHAR(8192),rules_version INT,profile_snapshot VARCHAR(8192),profile_version INT,created_at TIMESTAMP);
CREATE TABLE opportunity_material_items(id BIGINT PRIMARY KEY,opportunity_id BIGINT,name VARCHAR(128),description VARCHAR(512),required BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0,created_at TIMESTAMP);
CREATE TABLE opportunity_rule_snapshots(id BIGINT PRIMARY KEY,opportunity_id BIGINT,rules_version INT,rules_json VARCHAR(8192),material_requirements_json VARCHAR(8192),created_by BIGINT,created_at TIMESTAMP,UNIQUE(opportunity_id,rules_version));
CREATE TABLE favorites(id BIGINT PRIMARY KEY,user_id BIGINT,target_type VARCHAR(32),target_id BIGINT,created_at TIMESTAMP,UNIQUE(user_id,target_type,target_id));
CREATE TABLE reminders(id BIGINT PRIMARY KEY,user_id BIGINT,target_type VARCHAR(32),target_id BIGINT,remind_at TIMESTAMP,status VARCHAR(32) DEFAULT 'pending',created_at TIMESTAMP);
CREATE TABLE user_opportunity_submissions(id BIGINT PRIMARY KEY,user_id BIGINT,opportunity_id BIGINT,status VARCHAR(32) DEFAULT 'submitted',submitted_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(user_id,opportunity_id));
CREATE TABLE material_checklists(id BIGINT PRIMARY KEY,user_id BIGINT,opportunity_id BIGINT,status VARCHAR(32) DEFAULT 'draft',version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(user_id,opportunity_id));
CREATE TABLE material_checklist_items(id BIGINT PRIMARY KEY,checklist_id BIGINT,item_name VARCHAR(128),required BOOLEAN DEFAULT TRUE,material_version_id BIGINT,status VARCHAR(32) DEFAULT 'missing',created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE precheck_tasks(id BIGINT PRIMARY KEY,checklist_id BIGINT,user_id BIGINT,async_job_id BIGINT,status VARCHAR(32) DEFAULT 'pending',result_json VARCHAR(8192),checklist_version INT,rules_version INT,input_digest CHAR(64),input_snapshot VARCHAR(8192),model_config_version VARCHAR(64),claim_token CHAR(32),picked_at TIMESTAMP,next_retry_at TIMESTAMP,retry_count INT DEFAULT 0,ai_consent_id BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE precheck_results(id BIGINT PRIMARY KEY,precheck_task_id BIGINT,checklist_item_id BIGINT,item_key VARCHAR(64),level VARCHAR(16),message VARCHAR(512),evidence_json VARCHAR(4000),created_at TIMESTAMP);
